//! Write a database of invented writing sessions, for trying the program out.
//!
//!     cargo run --example demo_data -- /tmp/demo.db
//!     cargo run -- --db /tmp/demo.db
//!
//! The data is generated by `draft_tracker::demo`, which lives in the library so
//! that the tests cover it. This file is only the command line around it.

use std::path::PathBuf;
use std::process::ExitCode;

use draft_tracker::db::Db;
use draft_tracker::demo;

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1).map(PathBuf::from) else {
        eprintln!("usage: cargo run --example demo_data -- <path to a new database>");
        return ExitCode::FAILURE;
    };

    match write(&path) {
        Ok(message) => {
            println!("{message}");
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("demo_data: {error}");
            ExitCode::FAILURE
        }
    }
}

fn write(path: &PathBuf) -> anyhow::Result<String> {
    let mut db = Db::open(path)?;
    let summary = demo::populate(&mut db)?;

    Ok(format!(
        "Wrote demonstration data to {}\n\
         \n\
         {} projects in {} categories across {} types\n\
         {} sessions from {} to {}\n\
         {} words in {:.2} hours\n\
         \n\
         Open it with:  cargo run -- --db {}",
        path.display(),
        summary.projects,
        summary.categories,
        summary.types,
        summary.entries,
        summary.years.first().copied().unwrap_or_default(),
        summary.years.last().copied().unwrap_or_default(),
        summary.words,
        summary.hours,
        path.display(),
    ))
}
